"""Build the local review companion from the same layout data as the drawings."""
from build_plans import ROOT, LEVELS, esc

CSS='''
*{box-sizing:border-box}body{margin:0;background:#F5EFE6;color:#493C31;font:16px/1.5 system-ui,sans-serif}main{max-width:1280px;margin:auto;padding:26px}h1{font-size:34px;letter-spacing:-1px;margin:3px 0}h2{font-size:24px;line-height:1.25;margin:0 0 12px}h3{font-size:18px;margin:20px 0 8px}p{margin:8px 0 15px}.eyebrow{font-size:12px;font-weight:700;letter-spacing:.1em;color:#6A7C60}.intro{max-width:800px;color:#756553}.tabs,.routes,.links{display:flex;gap:8px;flex-wrap:wrap}.tabs{margin:24px 0 16px}button,a.pill{font:inherit;padding:9px 15px;border:1px solid #D8C6AF;border-radius:24px;color:#554636;background:#FFFDF7;cursor:pointer;text-decoration:none}button[aria-pressed=true]{background:#5D6951;color:#fff;border-color:#5D6951}button:focus-visible,a:focus-visible{outline:3px solid #397479;outline-offset:3px}.overview{background:#EEE5D4;padding:17px 20px;border-radius:14px}.overview strong{color:#397479}.layout{display:grid;grid-template-columns:minmax(0,1fr) 300px;gap:22px;align-items:start}.drawing{background:#F8F2E8;border:1px solid #E3D5C0;border-radius:18px;overflow:hidden}.drawing svg{width:100%;height:auto;display:block}.drawing.enlarged{overflow:auto}.drawing.enlarged svg{min-width:1000px}.routes{align-items:center;margin:0 0 10px}.routes button{font-size:13px;padding:7px 10px}.route-caption,.small{font-size:13px;color:#776753}.recipe{margin:0 0 10px;padding:12px 0;border-bottom:1px solid #DDCFBA}.recipe strong{display:block}.recipe span{font-size:14px}.stats{display:flex;gap:20px;flex-wrap:wrap;margin:13px 0}.stats span{font-size:13px;color:#776753}.stats b{display:block;color:#493C31;font-size:19px}.callout{border-left:3px solid #8D9D78;padding-left:14px}ol{padding-left:22px}li{margin:0 0 11px;font-size:14px}a{color:#397479}.actions{display:flex;justify-content:space-between;gap:10px;margin:12px 0 22px}.actions a{font-size:13px}.audit{margin:35px 0 20px;border-top:1px solid #D8C6AF;padding-top:24px}table{border-collapse:collapse;width:100%;font-size:14px}th,td{text-align:left;padding:12px 8px;border-bottom:1px solid #DDCFBA}th{font-weight:650}td:not(:first-child),th:not(:first-child){text-align:center}.state{font-size:13px;color:#60754F}.three{display:grid;grid-template-columns:repeat(3,1fr);gap:22px;margin:25px 0}.three p{font-size:14px}.guide{padding:20px 0;border-top:1px solid #D8C6AF}footer{font-size:13px;color:#776753;margin:30px 0 10px}.level[hidden]{display:none}@media(max-width:1020px){.layout{grid-template-columns:1fr}.details{display:grid;grid-template-columns:1fr 1fr;gap:24px}.details h2{font-size:21px}}@media(max-width:620px){main{padding:16px}h1{font-size:29px}.tabs button{font-size:14px;padding:8px 12px}.details,.three{grid-template-columns:1fr;gap:5px}.drawing.enlarged svg{min-width:900px}.stats{gap:15px}th,td{padding:9px 4px;font-size:12px}.actions{flex-wrap:wrap}}@media print{body{background:white}main{max-width:none;padding:0}.tabs,.routes,.actions,.overview,.audit,.guide,footer,header{display:none}.level[hidden]{display:block}.level{break-after:page}.layout{display:block}.drawing{border:0}.drawing svg{width:100%;max-height:220mm}.details{display:none}.route-caption{display:none}.three{display:none}}
'''

recipes={'salad':('<strong>Tomato–cucumber salad</strong><span>Chopped tomato + chopped cucumber<br>Serve on a clean plate.</span>'),
         'soup':('<strong>Carrot–mushroom soup</strong><span>Chopped carrot + chopped mushroom → cook<br>Serve in a clean bowl. No separate broth pickup.</span>')}

def level_markup(l):
    i=l['id'];svg=(ROOT/f'level-{i:02d}.svg').read_text()
    # IDs must stay unique when four SVG drawings share one document.
    import re
    svg=re.sub(r'\bid="([^"]+)"',lambda m:f'id="l{i}-{m.group(1)}"',svg)
    svg=re.sub(r'url\(#([^)]+)\)',lambda m:f'url(#l{i}-{m.group(1)})',svg)
    svg=svg.replace('aria-labelledby="title desc"',f'aria-labelledby="l{i}-title l{i}-desc"')
    svg=svg.replace('<svg ',f'<svg class="plan-svg" data-level="{i}" ')
    foodName='Salad route' if 'salad' in l['recipes'] else 'Soup route'
    routeButtons=f'<button data-route="food" aria-pressed="true">{foodName}</button>'
    if len(l['recipes'])>1:routeButtons+='<button data-route="soup" aria-pressed="false">Soup route</button>'
    routeButtons+='<button data-route="wash" aria-pressed="false">Dish reuse</button><button data-route="none" aria-pressed="false">Clear plan</button>'
    steps=''.join(f'<li>{esc(s)}</li>' for s in l['lessons'])
    return f'''<article id="level-{i}" class="level" {'' if i==1 else 'hidden'} aria-label="Level {i}: {esc(l['title'])}">
    <div class="routes" aria-label="Diagram routes">{routeButtons}</div>
    <p class="route-caption" aria-live="polite">{foodName}: numbered stops show task order. Repeat collection and chopping for the second ingredient.</p>
    <div class="layout"><section><div class="drawing">{svg}</div><div class="actions"><button class="zoom" aria-pressed="false">Enlarge plan</button><a href="level-{i:02d}.svg" target="_blank" rel="noopener">Open drawing ↗</a></div></section>
    <aside class="details"><div><div class="eyebrow">LEVEL {i} · {esc(l['skill'])}</div><h2>{esc(l['title'])}</h2><p>{esc(l['intention'])}</p>
    {''.join('<div class="recipe">'+recipes[r]+'</div>' for r in l['recipes'])}
    <div class="stats"><span><b>{l['cols']} × {l['rows']}</b>counter modules</span><span><b>{l['orders']}</b>orders to try</span><span><b>{l['active_orders']}</b>active tickets, max.</span></div>
    <p class="small">Starting dish pool: {l['dishes']['plates']} plates · {l['dishes']['bowls']} bowls. Wash and reuse; racks do not create new dishes. Order counts are proposals for testing.</p></div>
    <div><h3>How this level plays</h3><ol>{steps}</ol><p class="callout"><strong>Review focus</strong><br>{esc(l['review'])}</p></div></aside></div></article>'''

out=f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Bara Kitchen · Four level plans</title><style>{CSS}</style><main>
<header><div class="eyebrow">BARA KITCHEN · LEVEL REVIEW 01</div><h1>Four kitchens, one learning journey.</h1><p class="intro">Review the station placement, walking routes and ingredient coverage before we build the 3D rooms. These drawings use the approved café palette.</p></header>
<div class="overview"><strong>All four ingredients are covered.</strong> Tomato and cucumber make salad; carrot and mushroom make soup. Levels 3–4 combine them. No additional ingredient or third recipe is needed.</div>
<nav class="tabs" aria-label="Choose level">{''.join(f'<button data-select="{l["id"]}" aria-pressed="{str(l["id"]==1).lower()}">{l["id"]:02d} · {esc(l["title"])}</button>' for l in LEVELS)}</nav>
{''.join(level_markup(l) for l in LEVELS)}
<section class="audit"><div class="eyebrow">INGREDIENT COVERAGE</div><h2>One small food set supports the whole demo.</h2><table><thead><tr><th>Ingredient</th><th>Level 1</th><th>Level 2</th><th>Level 3</th><th>Level 4</th><th>Whole + chopped art</th></tr></thead><tbody>
{''.join('<tr><td>'+name.title()+'</td>'+''.join('<td>'+('●' if name in l['ingredients'] else '—')+'</td>' for l in LEVELS)+'<td class="state">Ready</td></tr>' for name in ['tomato','cucumber','carrot','mushroom'])}
</tbody></table><p class="small">● Used in this level. “Ready” means the 2D ingredient concepts exist; meshes and in-game states have not been built.</p>
<div class="three"><section><h3>Already drawn</h3><p>Four whole ingredients and four chopped forms; salad and soup; clean and dirty plates/bowls; chopping, cooking, serving and washing stations; supplies, counters and café furniture.</p><a href="../kitchen-round-01/">Review food & object art →</a></section>
<section><h3>States still to specify</h3><p>Tomato-only and cucumber-only salad assembly; pot with one/both ingredients, cooking, ready and burnt; progress and valid-throw feedback. These reuse existing ingredients and objects.</p></section>
<section><h3>Reuse across levels</h3><p>Landing areas are ordinary counters with a target highlight. The soup pot stays on the hob. The return uses a static tray first; an animated belt can use the same endpoint later.</p></section></div></section>
<section class="guide"><h2>Rules shared by these plans</h2><div class="three"><div><h3>One chef can do everything</h3><p>All station interaction edges connect to the walking space. Dash and throws are optional shortcuts. The chef carries one object at a time; route lines show task order, not simultaneous carrying.</p></div><div><h3>A complete dish loop</h3><p>Serve → customer eats → same dish returns dirty → wash → reuse. Customer seating is a separate presentation area. There is no manual table-delivery step in this first demo.</p></div><div><h3>Drawn, then tested</h3><p>The plan grid confirms access to every station. Character width, turning space, counter reach, camera visibility, throwing height and pacing still need a Unity blockout after review.</p></div></div>
<div class="links"><a class="pill" href="../../LEVEL_DESIGN.md">Full level design document</a><a class="pill" href="README.md">Drawings & source files</a><button id="print">Print four plans</button></div></section>
<footer>Proposed level layouts · 13 September 2026 · Food/environment art direction accepted; these floor plans await review.<br><a href="../kitchen-round-01/">Food and environment concepts</a> · <a href="../roster-round-02/">Character roster</a></footer></main>
<script>
function choose(id){{document.querySelectorAll('.level').forEach(p=>p.hidden=p.id!=='level-'+id);document.querySelectorAll('[data-select]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.select===id)));}}
document.querySelectorAll('[data-select]').forEach(b=>b.addEventListener('click',()=>choose(b.dataset.select)));
document.querySelectorAll('[data-route]').forEach(b=>b.addEventListener('click',()=>{{const article=b.closest('.level'),svg=article.querySelector('svg');svg.classList.remove('show-food','show-soup','show-wash','no-routes');svg.classList.add(b.dataset.route==='none'?'no-routes':'show-'+b.dataset.route);article.querySelectorAll('[data-route]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));article.querySelector('.route-caption').textContent=b.dataset.route==='none'?'Station layout without task routes. Skill shortcuts remain visible.':b.dataset.route==='wash'?'Dirty dish return → wash → correct clean-dish rack. Plate and bowl branches are alternatives, not a required tour of both racks.':b.textContent+': numbered stops show task order. Repeat collection and chopping for the second ingredient.';}}));
document.querySelectorAll('.zoom').forEach(b=>b.addEventListener('click',()=>{{const enlarged=b.closest('.level').querySelector('.drawing').classList.toggle('enlarged');b.setAttribute('aria-pressed',String(enlarged));b.textContent=enlarged?'Fit plan':'Enlarge plan';}}));document.getElementById('print').addEventListener('click',()=>window.print());
</script></html>'''
(ROOT/'index.html').write_text(out)
print('Built four-level review gallery')
